using System.Text.Json;
namespace DarkColony.ContentImport;
public sealed record AssetReceipt(string Path,long Bytes,string Sha256,string Source,string SourceHash,string Operation,string Version,string Parameters,long Stamp=0);
public sealed record ImportReceipt(int Contract,string BaseEdition,string? CouncilEdition,DateTime CreatedUtc,string[] Warnings,AssetReceipt[] Files,string ConversionRuntime="Unrecorded by earlier importer build");
public sealed class ContentStore {
 public static string DefaultPath=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"OpenDarkColony","Content");
 public string DirectoryPath {get;}
 public ContentStore(string path){DirectoryPath=Path.GetFullPath(path);SafePath.NoLinks(DirectoryPath);if(DirectoryPath==Path.GetPathRoot(DirectoryPath)||DirectoryPath.Length<8)throw new IOException("Choose a dedicated content folder, not a drive root");}
 public string? ActiveRoot {get {var p=Path.Combine(DirectoryPath,"active.json");if(!File.Exists(p))return null;using var doc=JsonDocument.Parse(File.ReadAllText(p));if(doc.RootElement.ValueKind!=JsonValueKind.Object||!doc.RootElement.TryGetProperty("generation",out var entry)||entry.ValueKind!=JsonValueKind.String||!Guid.TryParseExact(entry.GetString(),"N",out _))throw new InvalidDataException("Invalid active content generation; reimport the base game");return SafePath.Within(DirectoryPath,"generations/"+entry.GetString());}}
 public ImportReceipt? Receipt=>ActiveRoot is string root?ReadReceipt(root):null;
 internal static ImportReceipt ReadReceipt(string root){var r=JsonSerializer.Deserialize<ImportReceipt>(File.ReadAllText(Path.Combine(root,"content-manifest.json")));if(r==null||r.Contract!=ContentContract.Current.Revision||r.Files==null||r.Files.Length is <1900 or >12000)throw new InvalidDataException("Unsupported content contract; reimport using this OpenDC version");return r;}
 public string[] Validate(bool hashes,CancellationToken cancel,Action<ImportProgress>? progress=null){var root=ActiveRoot;if(root==null)return new[]{"No imported base game is installed."};return ValidateRoot(root,hashes,cancel,progress);}
 internal static string[] ValidateRoot(string root,bool hashes,CancellationToken cancel,Action<ImportProgress>? progress){var receipt=ReadReceipt(root);var errors=new List<string>();int done=0;var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var f in receipt.Files){cancel.ThrowIfCancellationRequested();string path=SafePath.Within(root,f.Path);SafePath.NoLinks(path);if(!seen.Add(f.Path))throw new InvalidDataException("Duplicate content receipt path");if(!File.Exists(path)||new FileInfo(path).Length!=f.Bytes||((hashes||f.Stamp!=File.GetLastWriteTimeUtc(path).Ticks)&&ContentContract.Hash(path)!=f.Sha256))errors.Add(f.Path);if(++done%32==0)progress?.Invoke(new(ImportStage.Validating,"Checking installed content",done,receipt.Files.Length,f.Path));}
  void Required(string path){if(!seen.Contains(path))errors.Add(path);}
  foreach(bool council in receipt.CouncilEdition==null?new[]{false}:new[]{false,true}){string data=council?"private/CouncilWars/":"private/DC/",movies=council?"generated/council-wars-first/video/":"generated/original-video/v1/";foreach(var f in council?ContentContract.Current.CouncilFiles:ContentContract.Current.BaseFiles){Required(data+f.Path);if(f.Role=="movie")Required(movies+Path.GetFileNameWithoutExtension(f.Path).ToLowerInvariant()+".odcv");}Required(data+"native-tables.json");if(council)Required(data+"odc-content.json");}
  foreach(string skin in new[]{"mission-frame","console-frame","circuit"})Required("generated/first-strike-ui/skin/"+skin+".png");return errors.Distinct().ToArray();}
 internal void Activate(string stage){string id=Guid.NewGuid().ToString("N"),generations=Path.Combine(DirectoryPath,"generations");SafePath.NoLinks(generations);Directory.CreateDirectory(generations);string dest=Path.Combine(generations,id);Directory.Move(stage,dest);string temp=Path.Combine(DirectoryPath,"active-"+id+".tmp");using(var f=new FileStream(temp,FileMode.CreateNew)){JsonSerializer.Serialize(f,new{generation=id,contract=ContentContract.Current.Revision});f.Flush(true);}File.Move(temp,Path.Combine(DirectoryPath,"active.json"),true);}
 internal FileStream Lock(){Directory.CreateDirectory(DirectoryPath);return new FileStream(Path.Combine(DirectoryPath,"import.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);}
 public string[] IncompleteImports()=>Directory.Exists(Path.Combine(DirectoryPath,"staging"))?System.IO.Directory.GetDirectories(Path.Combine(DirectoryPath,"staging")).Where(d=>File.Exists(Path.Combine(d,".odc-import-owned"))).Select(Path.GetFileName).OfType<string>().ToArray():Array.Empty<string>();
 public void CleanInterrupted(){using var locked=Lock();string parent=Path.Combine(DirectoryPath,"staging");foreach(string id in IncompleteImports()){if(!Guid.TryParseExact(id,"N",out _))continue;SafePath.DeleteOwnedStage(SafePath.Within(parent,id));}}
}
